// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 threshold, address claimer, address receiver, uint256 amount) public {
        // Bound threshold to a reasonable range (1 to 10000) to avoid overflow but ensure non-zero
        threshold = bound(threshold, 1, 10000);

        // Set the threshold via setThresholds (onlyOwner, so we need to be owner)
        vm.prank(c.owner());
        c.setThresholds(threshold);

        // Call claim with fuzzed parameters (may revert, but we don't care)
        (bool success,) = address(c).call(abi.encodeWithSelector(c.claim.selector, receiver, amount));

        // Now call setThresholds again with the same threshold
        vm.prank(c.owner());
        c.setThresholds(threshold);

        // Assert that slippageThresholdGmxBps equals the threshold we just set
        assertTrue(c.slippageThresholdGmxBps() == threshold);
    }
}

